### 🛠️ Production Implementation & Technical Verification

1. **Root Cause Analysis & Architectural Design**:

`uploadRoutes` configures Multer with memory storage but no byte limit or admission policy. Every multipart payload is therefore buffered in process memory, and any claimed MIME type or filename reaches the controller unchecked. The controller then treats an absent `req.file` as a successful upload (`201`, `status: "no-file"`).

The fix establishes the route as the security boundary:

- Multer enforces a hard 10 MiB stream limit before controller execution.
- A filename-extension and MIME-type allowlist requires a valid pair, preventing `.sh`, `.exe`, `.bat`, `.php`, double-extension, and MIME-spoof-by-extension uploads.
- Multer validation errors are translated into the repository’s `{ success: false, message }` 400 envelope.
- The controller remains the final invariant guard: no `req.file` can ever produce a successful response.

2. **Production-Grade Implementation Source Code**:

### Production Source (`apps/api/src/routes/uploadRoutes.js`)

```js
import { Router } from "express";
import multer from "multer";
import { uploadFile } from "../controllers/uploadController.js";
import { fail } from "../utils/response.js";

const MAX_FILE_SIZE_BYTES = 10 * 1024 * 1024;

const ALLOWED_UPLOAD_TYPES = new Map([
  ["image/png", new Set([".png"])],
  ["image/jpeg", new Set([".jpg", ".jpeg"])],
  ["image/webp", new Set([".webp"])],
  ["image/gif", new Set([".gif"])],
  ["application/pdf", new Set([".pdf"])],
  ["text/plain", new Set([".txt"])]
]);

function getExtension(filename) {
  if (typeof filename !== "string") {
    return "";
  }

  const normalizedName = filename.trim().toLowerCase();
  const dotIndex = normalizedName.lastIndexOf(".");

  return dotIndex > 0 ? normalizedName.slice(dotIndex) : "";
}

function isAllowedUpload(file) {
  const allowedExtensions = ALLOWED_UPLOAD_TYPES.get(file.mimetype?.toLowerCase());
  const extension = getExtension(file.originalname);

  return Boolean(allowedExtensions?.has(extension));
}

const upload = multer({
  storage: multer.memoryStorage(),
  limits: {
    fileSize: MAX_FILE_SIZE_BYTES,
    files: 1
  },
  fileFilter(req, file, callback) {
    if (!isAllowedUpload(file)) {
      return callback(
        new Error(
          "Unsupported file type. Allowed types are PNG, JPEG, WebP, GIF, PDF, and TXT."
        )
      );
    }

    return callback(null, true);
  }
}).single("file");

function handleUpload(req, res, next) {
  upload(req, res, (error) => {
    if (error) {
      if (error instanceof multer.MulterError) {
        if (error.code === "LIMIT_FILE_SIZE") {
          return fail(res, "File exceeds the 10MB limit", 400);
        }

        if (error.code === "LIMIT_FILE_COUNT") {
          return fail(res, "Only one file may be uploaded", 400);
        }

        if (error.code === "LIMIT_UNEXPECTED_FILE") {
          return fail(res, "No file provided", 400);
        }
      }

      return fail(
        res,
        error.message ||
          "Unsupported file type. Allowed types are PNG, JPEG, WebP, GIF, PDF, and TXT.",
        400
      );
    }

    return uploadFile(req, res, next);
  });
}

export const uploadRoutes = Router();

uploadRoutes.post("/", handleUpload);
```

### Production Source (`apps/api/src/controllers/uploadController.js`)

```js
import { fail, ok } from "../utils/response.js";

export async function uploadFile(req, res) {
  if (!req.file) {
    return fail(res, "No file provided", 400);
  }

  return ok(
    res,
    {
      filename: req.file.originalname,
      status: "uploaded"
    },
    201
  );
}
```

3. **Comprehensive Unit Test Suite & Verification Harness**:

### Test Suite (`apps/api/src/tests/upload.test.js`)

```js
import assert from "node:assert/strict";
import { after, before, test } from "node:test";
import { createApp } from "../app.js";

let server;
let baseUrl;

before(async () => {
  const app = createApp();

  await new Promise((resolve) => {
    server = app.listen(0, "127.0.0.1", resolve);
  });

  const address = server.address();
  baseUrl = `http://127.0.0.1:${address.port}`;
});

after(async () => {
  await new Promise((resolve, reject) => {
    server.close((error) => (error ? reject(error) : resolve()));
  });
});

async function postUpload({ filename, mimetype, content }) {
  const form = new FormData();
  form.set(
    "file",
    new Blob([content], { type: mimetype }),
    filename
  );

  return fetch(`${baseUrl}/api/uploads`, {
    method: "POST",
    body: form
  });
}

test("POST /api/uploads accepts a whitelisted PDF upload", async () => {
  const response = await postUpload({
    filename: "architecture.pdf",
    mimetype: "application/pdf",
    content: "%PDF-1.7\nsecure upload regression fixture\n"
  });

  assert.equal(response.status, 201);
  assert.deepEqual(await response.json(), {
    success: true,
    data: {
      filename: "architecture.pdf",
      status: "uploaded"
    }
  });
});

test("POST /api/uploads rejects a request without a file", async () => {
  const response = await fetch(`${baseUrl}/api/uploads`, {
    method: "POST",
    body: new FormData()
  });

  assert.equal(response.status, 400);
  assert.deepEqual(await response.json(), {
    success: false,
    message: "No file provided"
  });
});

test("POST /api/uploads rejects files larger than 10MB", async () => {
  const oversizedContent = Buffer.alloc((10 * 1024 * 1024) + 1, 0x61);

  const response = await postUpload({
    filename: "oversized.txt",
    mimetype: "text/plain",
    content: oversizedContent
  });

  assert.equal(response.status, 400);
  assert.deepEqual(await response.json(), {
    success: false,
    message: "File exceeds the 10MB limit"
  });
});

test("POST /api/uploads rejects executable extensions even when MIME claims text/plain", async () => {
  const response = await postUpload({
    filename: "deploy.sh",
    mimetype: "text/plain",
    content: "#!/bin/sh\necho unsafe\n"
  });

  assert.equal(response.status, 400);
  assert.deepEqual(await response.json(), {
    success: false,
    message:
      "Unsupported file type. Allowed types are PNG, JPEG, WebP, GIF, PDF, and TXT."
  });
});
```

Run the focused regression suite from `apps/api`:

```bash
node --test src/tests/upload.test.js
```

Run the complete API suite:

```bash
npm test
```

